<template>
  <div :class="{'app-container': !embedded}" v-loading="loading"><template v-if="!embedded"><el-alert title="从 jdp_tb_refund 同步到平台退款，再按店铺设置转业务退款单。资金操作和仓库截单不会由同步任务自动执行。" type="info" :closable="false" show-icon /><p class="hint">JDP 并不覆盖所有交易完成后的售后及专项退款。超出覆盖范围须到平台核对，本页不会把推送库未找到判定为申请不存在。</p><el-button size="small" @click="load">刷新配置</el-button><el-table :data="shops"><el-table-column label="店铺" min-width="200"><template slot-scope="s">{{ s.row.channel_name }}<div class="hint">渠道 ID {{ s.row.channel_id }}</div></template></el-table-column><el-table-column label="自动同步" width="110"><template slot-scope="s">{{ s.row.enabled ? '已开启' : '未开启' }}</template></el-table-column><el-table-column label="自动转单" width="130"><template slot-scope="s">{{ s.row.auto_convert ? '保存后自动转单' : '人工转单' }}</template></el-table-column><el-table-column label="退款同步进度" min-width="230"><template slot-scope="s">{{ s.row.cursor_time || '尚未配置' }}<div class="hint">最近成功 {{ s.row.last_success || '—' }}</div><div class="warning">{{ s.row.last_error }}</div></template></el-table-column><el-table-column label="操作" width="180"><template slot-scope="s"><el-button type="text" @click="open(s.row)">配置</el-button><el-button v-if="s.row.revision" type="text" @click="test(s.row)">检查退款表</el-button></template></el-table-column></el-table>
    </template><el-dialog title="店铺退款接入" :visible.sync="visible" width="720px" append-to-body :close-on-click-modal="false"><el-form v-if="form" label-width="140px"><el-form-item label="店铺">{{ form.channel_name }}</el-form-item><el-form-item label="推送库" required><el-select v-model="form.source_key" :disabled="!!form.revision" style="width:100%"><el-option v-for="s in (embedded ? sourceOptions : sources)" :key="s.key" :value="s.key" :label="s.label" :disabled="!s.enabled" /></el-select><div class="hint">复用已有推送库连接池；退款独立检查 jdp_tb_refund。地址与凭证在推送库配置中维护。</div></el-form-item><el-form-item label="推送库卖家昵称" required><el-input v-model="form.seller_nick" :disabled="!!form.revision" maxlength="200" /><div class="hint">必须与本店铺在推送库中的 seller_nick 一致，保存后固定。</div></el-form-item><el-form-item label="首次同步时间" required><el-date-picker v-model="form.initial_time" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" :disabled="!!form.revision" /><div class="hint">退款独立游标，首次保存后不回退；遗漏使用补拉任务。</div></el-form-item><el-form-item v-if="form.revision" label="退款读取检查"><el-button size="small" @click="test(form)">检查退款推送库</el-button></el-form-item><el-form-item label="自动同步"><el-switch v-model="form.enabled" :active-value="1" :inactive-value="0" /></el-form-item><el-form-item label="自动转业务退款"><el-switch v-model="form.auto_convert" :active-value="1" :inactive-value="0" /><div class="hint">默认关闭。转单不代表同意退款或自动处理货物。</div></el-form-item><el-form-item label="扫描间隔"><el-input-number v-model="form.interval_seconds" :min="10" :max="3600" :precision="0" /> 秒</el-form-item></el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存配置</el-button></span></el-dialog>
  </div>
</template>
<script>
import { refundConfigs, saveRefundConfig, testRefundConfig } from '@/api/order/refund'
export default { name: 'RefundSettings', props: { embedded: Boolean, sourceOptions: { type: Array, default: () => [] } }, data: () => ({ loading: false, saving: false, shops: [], sources: [], visible: false, form: null }), created() { if(!this.embedded)this.load() }, methods: {
  async load() { this.loading = true; try { const r = (await refundConfigs()).data; this.sources = r.sources; this.shops = r.channels.filter(c => c.channel_type === 'TM').map(c => ({ ...c, enabled: 0, auto_convert: 0, interval_seconds: 30, ...(r.configs.find(s => Number(s.channel_id) === Number(c.channel_id)) || {}) })) } finally { this.loading = false } },
  open(r) { this.form = { ...r, revision: r.revision || 0, source_key: r.source_key || '', seller_nick: r.seller_nick || '', initial_time: r.initial_time || '' }; this.visible = true },
  async save() { this.saving = true; try { await saveRefundConfig(this.form); this.$message.success('退款接入配置已保存'); this.visible = false; this.$emit('changed'); if(!this.embedded)await this.load() } finally { this.saving = false } },
  async test(r) { await testRefundConfig(r.channel_id); this.$message.success('退款推送库结构检查通过；未推进游标') }
} }
</script>
<style scoped>.hint{color:#8492a6;font-size:12px;line-height:1.8}.warning{color:#b77515}</style>
